class Solution {
    public int atMostNGivenDigitSet(String[] digits,int n){
        String text=Integer.toString(n);
        int base=digits.length,answer=0;
        for(int length=1;length<text.length();length++)answer+=power(base,length);
        for(int i=0;i<text.length();i++){
            int less=0;
            boolean equal=false;
            for(String digit:digits){
                if(digit.charAt(0)<text.charAt(i))less++;
                else if(digit.charAt(0)==text.charAt(i))equal=true;
            }
            answer+=less*power(base,text.length()-1-i);
            if(!equal)return answer;
        }
        return answer+1;
    }
    private int power(int base,int exponent){
        int result=1;
        while(exponent-->0)result*=base;
        return result;
    }
}

